class Solution {
public:
    string reorganizeString(string s) {
        vector<int> counts(26, 0);
        for (char c : s) counts[c - 'a']++;
        int max_freq = 0;
        for (int c : counts) max_freq = max(max_freq, c);
        if (max_freq > ((int)s.length() + 1) / 2) return "";
        priority_queue<pair<int, char>> pq;
        for (int i = 0; i < 26; i++) {
            if (counts[i] > 0) pq.push({counts[i], (char)('a' + i)});
        }
        string res = "";
        while (pq.size() >= 2) {
            auto [cnt1, ch1] = pq.top(); pq.pop();
            auto [cnt2, ch2] = pq.top(); pq.pop();
            res.push_back(ch1);
            res.push_back(ch2);
            if (cnt1 - 1 > 0) pq.push({cnt1 - 1, ch1});
            if (cnt2 - 1 > 0) pq.push({cnt2 - 1, ch2});
        }
        if (!pq.empty()) res.push_back(pq.top().second);
        return res;
    }
};

class Solution {
    public String reorganizeString(String s) {
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        int maxFreq = 0;
        for (int c : counts) maxFreq = Math.max(maxFreq, c);
        if (maxFreq > (s.length() + 1) / 2) return "";
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < 26; i++) {
            if (counts[i] > 0) pq.offer(new int[]{counts[i], i});
        }
        StringBuilder sb = new StringBuilder();
        while (pq.size() >= 2) {
            int[] first = pq.poll();
            int[] second = pq.poll();
            sb.append((char)('a' + first[1]));
            sb.append((char)('a' + second[1]));
            if (first[0] - 1 > 0) pq.offer(new int[]{first[0] - 1, first[1]});
            if (second[0] - 1 > 0) pq.offer(new int[]{second[0] - 1, second[1]});
        }
        if (!pq.isEmpty()) sb.append((char)('a' + pq.poll()[1]));
        return sb.toString();
    }
}

var reorganizeString = function(s) {
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) counts[s.charCodeAt(i) - 97]++;
    let maxFreq = 0, maxCharIdx = 0;
    for (let i = 0; i < 26; i++) {
        if (counts[i] > maxFreq) {
            maxFreq = counts[i];
            maxCharIdx = i;
        }
    }
    if (maxFreq > Math.floor((s.length + 1) / 2)) return "";
    const res = new Array(s.length);
    let idx = 0;
    while (counts[maxCharIdx] > 0) {
        res[idx] = String.fromCharCode(97 + maxCharIdx);
        idx += 2;
        counts[maxCharIdx]--;
    }
    for (let i = 0; i < 26; i++) {
        while (counts[i] > 0) {
            if (idx >= s.length) idx = 1;
            res[idx] = String.fromCharCode(97 + i);
            idx += 2;
            counts[i]--;
        }
    }
    return res.join('');
};
